#pragma config(Sensor, dgtl3,        frontLimit,     sensorTouch)
#pragma config(Motor,  port1,        rightMotor,     tmotorVex393_HBridge, openLoop, reversed)
#pragma config(Motor,  port2,        clawServo,      tmotorServoStandard, openLoop)
#pragma config(Motor,  port3,        pressArmServo,  tmotorServoStandard, openLoop)
#pragma config(Motor,  port10,       leftMotor,      tmotorVex393_HBridge, openLoop, reversed)
//*!!Code automatically generated by 'ROBOTC' configuration wizard               !!*//

/*
  Drive calibration for robot_project.c. The robot finds its way back to the start
  by estimating its position from motor power and time, so it needs three numbers
  measured on YOUR robot, on the arena floor, with a charged battery:

  TEST 1 (straight): press and release the front switch. The robot drives
  straight forward for 3 seconds. Measure how far it went, in cm.
      MAX_WHEEL_SPEED_CM_PER_SEC = test 1 distance x 0.94

  TEST 2 (spin): press and release the front switch. The robot spins in place
  for 3 seconds. Estimate how many degrees it turned (one full turn = 360).
      TRACK_WIDTH_CM = MAX_WHEEL_SPEED_CM_PER_SEC x 135 / degrees

  TEST 3 (pulling): press and release the front switch. The claw opens: within
  5 seconds, stand the green beacon in the claw. The arm presses down, the claw
  closes, and the robot backs up for 3 seconds pulling the beacon. Measure how
  far it went, in cm.
      PULL_SPEED_FACTOR = test 3 distance / test 1 distance

  Put the three numbers in robot_project.c. Doing each test 2-3 times and taking
  the average gives better numbers.

  Keep the powers and servo positions below the same as in robot_project.c.
*/

#define DRIVE_POWER               45   // FORWARD_SPEED / RETURN_BACKWARD_POWER
#define SPIN_POWER                50   // SEARCH_SPIN_SPEED
#define TEST_TIME_MS            3000

#define CLAW_OPEN_POS            -80
#define CLAW_CLOSED_POS           60
#define PRESS_ARM_HOME_POS       -80
#define PRESS_ARM_HOLD_GREEN_POS  60
#define SERVO_MOVE_TIME_MS       650

void WaitForSwitch()
{
    while(SensorValue[frontLimit] == 0)
        wait1Msec(10);
    while(SensorValue[frontLimit] == 1)
        wait1Msec(10);
    wait1Msec(1000);
}

// Same motor polarity as robot_project.c: right = -power, left = +power drives forward.
void Drive(int rightPower, int leftPower, int durationMs)
{
    motor[rightMotor] = rightPower;
    motor[leftMotor] = leftPower;
    wait1Msec(durationMs);
    motor[rightMotor] = 0;
    motor[leftMotor] = 0;
}

task main()
{
    clearDebugStream();
    motor[clawServo] = CLAW_OPEN_POS;
    motor[pressArmServo] = PRESS_ARM_HOME_POS;

    writeDebugStreamLine("TEST 1: press switch, drives 3 s");
    WaitForSwitch();
    Drive(-DRIVE_POWER, DRIVE_POWER, TEST_TIME_MS);
    writeDebugStreamLine("MAX_WHEEL_SPEED = cm x 0.94");

    writeDebugStreamLine("TEST 2: press switch, spins 3 s");
    WaitForSwitch();
    Drive(-SPIN_POWER, -SPIN_POWER, TEST_TIME_MS);   // same spin as the beacon search
    writeDebugStreamLine("TRACK_WIDTH = MAX x 135 / degrees");

    writeDebugStreamLine("TEST 3: press switch, then put green in claw");
    WaitForSwitch();
    motor[clawServo] = CLAW_OPEN_POS;
    wait1Msec(5000);
    motor[pressArmServo] = PRESS_ARM_HOLD_GREEN_POS;
    wait1Msec(SERVO_MOVE_TIME_MS);
    motor[clawServo] = CLAW_CLOSED_POS;
    wait1Msec(SERVO_MOVE_TIME_MS);
    Drive(DRIVE_POWER, -DRIVE_POWER, TEST_TIME_MS);   // backward
    writeDebugStreamLine("PULL_SPEED_FACTOR = test 3 cm / test 1 cm");

    while(true)
        wait1Msec(100);
}
